set_error_handler(function($severity,$message){echo 'diagnostic:', $severity, ':', $message, "\n";return true;});
function show($name,$value){echo $name,':',json_encode($value,JSON_UNESCAPED_SLASHES),"\n";}
function failure($name,$call){try{show($name,$call());}catch(Throwable $e){show($name,[get_class($e),$e->getMessage()]);}}
function cases($name,$call){if(getenv('RPHP_ARRAY_OBJECT_CASE')!==$name)return;echo "case:",$name,"\n";failure('outcome',$call);}
cases('metadata',function(){foreach(['ArrayObject','ArrayIterator']as$c){foreach(['__construct','getFlags','setFlags']as$m){$r=new ReflectionMethod($c,$m);$p=[];foreach($r->getParameters()as$a){$p[]=[$a->getName(),(string)$a->getType(),$a->isOptional(),$a->isDefaultValueAvailable()?$a->getDefaultValue():null];}show($c.'::'.$m,[$r->getNumberOfRequiredParameters(),$p,(string)$r->getTentativeReturnType()]);}}});
