cases('nested',function(){foreach(['ArrayObject','ArrayIterator']as$c){$base=new ArrayObject(['entry'=>9],3);$inherit=new $c($base);$zero=new $c($base,0);show($c,[$base->getFlags(),$inherit->getFlags(),$zero->getFlags()]);$base->setFlags(1);show('after-base',[$inherit->getFlags(),$zero->getFlags()]);$inherit->setFlags(2);show('after-child',[$base->getFlags(),$inherit->getFlags()]);$inherit->__construct($base);show('reconstructed',$inherit->getFlags());}});
