cases('references',function(){$number=6;$input=['key'=>&$number];$o=new ArrayObject($input,2);$alias=&$o->key;$alias=11;show('alias',[$number,$o['key']]);$copy=$o->getArrayCopy();$o->other=4;show('cow',[$copy,$o->getArrayCopy(),$input]);unset($o->key);$alias=15;show('unset',[$number,isset($o->key),$alias]);});
